// Reduced from `solid-js@2.0.0-rc.9`. Unlike rc.3, `createRoot` is its own export:
// `types/client/hydration.d.ts` imports the signals one as `coreRoot` and
// declares the const below (byte-faithful), which `types/index.d.ts:8`
// re-exports. `flush`, `onSettled`, `refresh` and `untrack` are re-exported
// from `@solidjs/signals` as `types/index.d.ts:1` does. `createMemo`,
// `createSignal`, `createStore` and `createEffect` are hydration consts as on
// rc.3, and are re-exported from signals here for the same reason.
import { createRoot as coreRoot } from "@solidjs/signals";
export declare const createRoot: typeof coreRoot;
export { flush, onSettled, refresh, untrack } from "@solidjs/signals";
export { createEffect, createMemo, createSignal, createStore } from "@solidjs/signals";
